class MobilityEnforcementModule(ModuleBase):
    def __init__(self, rng: random.Random):
        super().__init__("MobilityEnforcement", rng)
    def forward(self, state, buffers, params, t):
        persons: List[Person] = state["persons"]
        locations: List[Location] = state.get("locations", [])
        gov: PolicyMaker = state.get("policy_maker")
        violation_events = 0
        # simple schedule: household mornings/evenings; workplace weekdays; public mid-day
        for p in persons:
            # pick a location based on time slice and p attributes (placeholder)
            loc = locations[self.rng.randrange(len(locations))] if locations else None
            if not loc:
                continue
            # enforcement
            if gov.mandate_active and loc.mask_requirement and p.mask_adoption_state == 0:
                if self.rng.random() < gov.enforcement_probability * loc.enforcement_level:
                    violation_events += 1
                    # apply fine and adjust compliance
                    p.compliance_propensity = clamp(p.compliance_propensity + 0.05, 0.0, 1.0)
        observables = {"violation_events_daily": violation_events}
        signals = buffers.get("signals", {})
        return {"person_updates": {}, "location_updates": {}, "retailer_updates": {}, "global_updates": {}, "signals": signals, "observables": observables, "io": {}}

