class GovernmentPolicyModule(ModuleBase):
    def forward(self, state, buffers, params, t):
        pm: PolicyMaker = state["policy_maker"]
        start_day = int(params.get("policy_start_day", 30))
        if t == start_day:
            pm.mandate_active = True if params.get("mandate_strictness", 0.7) > 0 else False
        # Simple adaptive enforcement: increase if violation_rate high (from previous day)
        obs_prev = state.get("last_observables", {})
        vr = obs_prev.get("violation_rate_daily", 0.0)
        if vr > 0.2:
            pm.enforcement_probability = clamp(pm.enforcement_probability + 0.05, 0.0, 1.0)
        global_updates = {"policy_maker": {"mandate_active": pm.mandate_active, "enforcement_probability": pm.enforcement_probability}}

