def scale_free_graph(n: int, m: int, rng: random.Random) -> List[List[int]]:
    if n <= 0 or m <= 0:
        return [[] for _ in range(max(0, n))]
    adj: List[Set[int]] = [set() for _ in range(n)]
    # seed clique
    core = min(n, m + 1)
    for i in range(core):
        for j in range(i + 1, core):
            adj[i].add(j); adj[j].add(i)
    # repeated-node list for O(1) expected sampling
    stubs: List[int] = []
    for i in range(core):
        stubs.extend([i] * len(adj[i]))
    for new in range(core, n):
        targets = set()
        while len(targets) < min(m, max(1, len(stubs))):
            t = rng.choice(stubs) if stubs else rng.randrange(0, new)
            if t != new:
                targets.add(t)
        for t in targets:
            adj[new].add(t); adj[t].add(new)
            stubs.append(t); stubs.append(new)
        if not targets:
            t = rng.randrange(0, new)
            adj[new].add(t); adj[t].add(new)
            stubs.append(t); stubs.append(new)
    return [list(s) for s in adj]
